import json,pathlib,re,html
rows=json.loads("[[\"isetan-shinjuku-b1-food\",\"이세탄 신주쿠 본관 B1: 데파치카\",\"본관 지하 1층은 식품관입니다. 서양 과자·일본 과자, 빵, 조리식품과 선물을 매장별로 확인하세요.\",\"남성관과 본관을 혼동하지 말고 본관 B1 플로어맵의 브랜드와 연결통로를 확인하세요.\",\"https://www.mistore.jp/store/shinjuku/shops/mainfloorB1.html\"],[\"isetan-shinjuku-1f-cosmetics\",\"이세탄 신주쿠 본관 1F: 코스메틱\",\"본관 1층에는 화장품·향수·잡화·주얼리 관련 매장이 있습니다.\",\"원하는 브랜드의 위치와 면세 서비스 카운터를 공식 1F 지도로 확인하세요.\",\"https://www.mistore.jp/store/shinjuku/shops/mainfloor1.html\"],[\"isetan-shinjuku-b2-beauty\",\"이세탄 신주쿠 본관 B2: 뷰티 아포세카리\",\"본관 지하 2층은 이세탄 뷰티 아포세카리 중심으로, 식품관인 B1과 상품 구성이 다릅니다.\",\"자연주의 화장품·향기·헤어케어 취급 브랜드와 영업 일정은 당일 플로어 가이드에서 확인하세요.\",\"https://www.mistore.jp/store/shinjuku/shops.html\"],[\"isetan-shinjuku-mens\",\"이세탄 남성관: 별도 건물\",\"남성 패션·신발·잡화는 신주쿠 이세탄 남성관에서 찾습니다. 본관 B1 식품관과 별도 건물입니다.\",\"남성관 층별 편집 브랜드와 본관 연결 동선을 정확한 현재 공식 지도로 확인하세요.\",\"https://www.imn.jp/en/floorguide\"],[\"daimaru-tokyo-b1-food\",\"다이마루 도쿄 B1: 식품관\",\"도쿄역 야에스 북쪽 방향 다이마루 도쿄점의 B1 식품 매장을 먼저 확인하세요.\",\"도시락·과자·선물 구입 전 도쿄역 출발 시간과 유통기한·보관 조건을 확인하세요.\",\"https://www.daimaru.co.jp/tokyo/floor/\"],[\"daimaru-tokyo-12f-taxfree\",\"다이마루 도쿄 12F: 식당·면세\",\"공식 플로어 가이드 기준 12층은 레스토랑과 면세 카운터가 있습니다.\",\"면세 대상 품목·여권 제시·접수 마감·환급 조건은 구매 당일 카운터 안내를 확인하세요.\",\"https://www.daimaru.co.jp/tokyo/floor/12f.html\"],[\"daimaru-tokyo-10f-hands\",\"다이마루 도쿄 10F: 핸즈\",\"공식 가이드 기준 10층에는 핸즈와 아트·취미·문화 분야 매장이 있습니다.\",\"도구·문구·생활용품은 상품군이 넓으므로 취급 브랜드와 세부 매장 위치를 미리 확인하세요.\",\"https://www.daimaru.co.jp/tokyo/floor/10f.html\"],[\"tobu-ikebukuro-b1-b2\",\"도부 이케부쿠로 B1·B2\",\"이케부쿠로 서쪽 도부 백화점의 지하 식품관을 B1·B2 층별 안내에서 구분합니다.\",\"푸드코트·디저트·도시락 매장 및 판매 브랜드가 바뀔 수 있어 현재 플로어맵을 확인하세요.\",\"https://www.tobu-dept.jp/ikebukuro/\"],[\"tobu-ikebukuro-7f-kids\",\"도부 이케부쿠로 7F 아동 매장\",\"아동복·장난감·서점의 현재 입점층과 매장을 방문 전 도부 플로어 가이드에서 다시 확인하세요.\",\"유모차·수유실·키즈 시설은 층별 편의시설 표시를 확인하세요.\",\"https://www.tobu-dept.jp/ikebukuro/\"],[\"tobu-ikebukuro-restaurants\",\"도부 이케부쿠로 식당가\",\"도부 백화점 스파이스 식당가의 현재 층별 매장 목록과 마감 주문 시간을 확인하세요.\",\"백화점 일반 매장과 음식점은 운영시간이 다를 수 있으므로 동일하게 보지 마세요.\",\"https://www.tobu-dept.jp/ikebukuro/\"],[\"shinjuku-takashimaya-b1\",\"신주쿠 다카시마야 B1\",\"신주쿠 다카시마야의 지하 식품 매장과 연결 건물 동선을 공식 지도로 확인하세요.\",\"신주쿠역 신남쪽 출구에서 목적 건물까지 이동시간을 포함하고 냉장 식품은 마지막에 구매하세요.\",\"https://www.takashimaya.co.jp/shinjuku/\"],[\"shinjuku-takashimaya-9f-kids\",\"신주쿠 다카시마야 아동·유아 상품\",\"현재 9층 상품 배치가 유지되는지 공식 플로어 가이드를 먼저 확인한 뒤 아동복·육아용품 매장을 찾으세요.\",\"베이비 휴게실·엘리베이터 위치는 유모차 이동에 중요하므로 층별 편의시설 지도를 확인하세요.\",\"https://www.takashimaya.co.jp/shinjuku/\"],[\"ginza-six-b2-food\",\"GINZA SIX B2 식품·디저트\",\"긴자식스 지하 2층 식품·디저트 매장을 공식 층별 지도에서 확인하세요.\",\"개별 브랜드·팝업 입점이 바뀔 수 있고 냉장 디저트는 보관시간을 먼저 확인하세요.\",\"https://ginza6.tokyo/floor\"],[\"ginza-six-b1-beauty\",\"GINZA SIX B1 뷰티\",\"긴자식스 지하 1층의 최신 뷰티·코스메틱 매장과 화장품 브랜드를 공식 플로어 가이드에서 확인하세요.\",\"면세 서비스 위치와 브랜드별 구매 조건은 점포에서 따로 확인하세요.\",\"https://ginza6.tokyo/floor\"],[\"ginza-six-6f-books\",\"GINZA SIX 6F 서점·문화\",\"긴자식스 6층의 서점·예술·카페 관련 현재 입점 상태를 플로어 가이드에서 확인하세요.\",\"전시·행사 일정과 개별 카페 좌석·영업시간은 점포별로 다를 수 있습니다.\",\"https://ginza6.tokyo/floor\"],[\"ginza-six-rooftop\",\"GINZA SIX 옥상정원\",\"GINZA SIX 옥상정원은 매장 쇼핑과 별개의 방문 공간입니다. 개방시간·날씨에 따른 입장제한을 확인하세요.\",\"옥상 접근 엘리베이터·에스컬레이터 경로를 현장 시설 안내표로 확인하세요.\",\"https://ginza6.tokyo/\"],[\"nihombashi-mitsukoshi-floors\",\"니혼바시 미쓰코시 본관·신관\",\"본관과 신관은 구분된 건물이므로 원하는 브랜드와 레스토랑 층을 공식 층별 안내에서 구분하세요.\",\"지하 연결통로와 면세 카운터 위치를 먼저 확인해 건물 사이 재이동을 줄이세요.\",\"https://www.mistore.jp/store/nihombashi.html\"],[\"ginza-mitsukoshi-floor-plan\",\"긴자 미쓰코시 층별 쇼핑\",\"긴자 미쓰코시는 본관·신관의 식품관·뷰티·면세 안내가 다를 수 있으므로 건물과 층을 동시에 확인하세요.\",\"긴자역 연결 입구와 주말 혼잡을 고려해 주요 구매품목부터 방문하세요.\",\"https://www.mistore.jp/store/ginza.html\"],[\"nihombashi-takashimaya-floor\",\"니혼바시 다카시마야 건물별 안내\",\"본관·신관·워치 메종 등 목적 시설을 구분하고 공식 안내에서 점포와 층을 확인하세요.\",\"지하철 니혼바시역 출구와 건물 연결 통로, 엘리베이터 위치를 확인하세요.\",\"https://www.takashimaya.co.jp/nihombashi/\"],[\"shibuya-parco-floor-guide\",\"시부야 PARCO 층별 쇼핑\",\"캐릭터 매장·패션·식당은 층마다 분리되어 있으므로 공식 층별 안내에서 현재 위치를 확인하세요.\",\"한정 상품은 예약·대기·입장 정리권을 운영할 수 있으며 각 브랜드의 공지가 우선입니다.\",\"https://shibuya.parco.jp/floor/\"]]")
base=pathlib.Path("site/japan/tokyo")
records=[]
for slug,title,a,b,url in rows:
 p=base/slug/"index.html"
 s=p.read_text(encoding="utf-8")
 assert "<article>" in s and "tokyo-editorial-v121" not in s,slug
 sec='<section class="tky-block tokyo-editorial-v121" id="floor-guide"><h2>'+html.escape(title)+'</h2><p>'+html.escape(a)+'</p><p>'+html.escape(b)+'</p><p><a href="'+html.escape(url,quote=True)+'" rel="noopener noreferrer" target="_blank">백화점 공식 플로어 가이드 확인 ↗</a></p><p class="tky-dated">층별 상품·매장 위치는 수시로 변경되므로 방문 시점 공식 지도와 현장 안내가 기준입니다.</p></section>'
 s=s.replace("<article>","<article>"+sec,1)
 rem=[]
 for label,pattern in [
 ("intro",r'<section class="tky-block"><div class="tky-dated">.*?<h2>이 주제를 선택하기 전에</h2>.*?</section>'),
 ("route",r'<section class="tky-block" id="plan"><h2>시간 낭비를 줄이는 실제 여행 동선</h2>.*?</section>'),
 ("ticket",r'<section class="tky-block" id="tickets"><h2>가격·영업시간·예약에서 놓치기 쉬운 조건</h2>.*?</section>'),
 ("faq",r'<section class="tky-block"><h2>자주 묻는 질문</h2>.*?</section>'),
 ("generic",r'<section class="tky-block"><h2>방문자가 가장 많이 혼동하는 세 가지</h2>.*?</section>'),
 ("field",r'<section class="tky-block tokyo-field-check-v307"[^>]*>.*?</section>')
 ]:
  s,n=re.subn(pattern,"",s,count=1,flags=re.S)
  if n:rem.append(label)
 s=s.replace('href="#plan"','href="#floor-guide"').replace('href="#tickets"','href="#floor-guide"')
 p.write_text(s,encoding="utf-8")
 records.append({"slug":slug,"generic_removed":rem})
pathlib.Path("audit-reports/tokyo-v121-v140-editorial-upgrade.json").write_text(json.dumps({"updated":len(records),"removed":sum(len(x["generic_removed"]) for x in records),"pages":records,"caveat":"Official floor guides linked, but store inventories and individual business operations need date-specific confirmation."},ensure_ascii=False,indent=2))
print("updated",len(records))
